import{_ as e,o as a,c as n,a2 as d}from"./chunks/framework.A5mep7Fe.js";const s=JSON.parse('{"title":"🤖 03 · 算法岗 · AI Agent（智能体）","description":"","frontmatter":{},"headers":[],"relativePath":"03-算法岗-AI-Agent/index.md","filePath":"03-算法岗-AI-Agent/README.md","lastUpdated":1786806808000}'),r={name:"03-算法岗-AI-Agent/index.md"};function o(l,t,i,h,A,g){return a(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="🤖-03-·-算法岗-·-ai-agent-智能体" tabindex="-1">🤖 03 · 算法岗 · AI Agent（智能体） <a class="header-anchor" href="#🤖-03-·-算法岗-·-ai-agent-智能体" aria-label="Permalink to &quot;🤖 03 · 算法岗 · AI Agent（智能体）&quot;">​</a></h1><blockquote><p>2024-2026 增长最快的岗位方向。相比「训练模型」，Agent 更偏<strong>工程化编排 + 系统设计</strong>。本篇是面试高频重灾区，务必吃透范式而非某个库。</p></blockquote><hr><h2 id="本篇导航" tabindex="-1">本篇导航 <a class="header-anchor" href="#本篇导航" aria-label="Permalink to &quot;本篇导航&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>核心内容</th><th>标签</th></tr></thead><tbody><tr><td><a href="./01-Agent架构范式">01-Agent 架构范式</a></td><td>ReAct、Plan-and-Execute、Reflexion、多范式对比</td><td>🟢 核心</td></tr><tr><td><a href="./02-RAG检索增强">02-RAG 检索增强</a></td><td>分块/嵌入/检索/重排/评估，进阶 RAG</td><td>🟢 核心</td></tr><tr><td><a href="./03-记忆系统与工具调用">03-记忆系统与工具调用</a></td><td>短期/长期记忆、Function Calling、工具路由</td><td>🟢 核心</td></tr><tr><td><a href="./04-MCP与多Agent">04-MCP 与多 Agent</a></td><td>MCP 协议、A2A、多智能体协作、冲突解决</td><td>🟡 工程</td></tr><tr><td><a href="./05-Agent工程化与评估">05-Agent 工程化与评估</a></td><td>可靠性、可观测、降级、评测体系</td><td>🟡 工程</td></tr></tbody></table><hr><h2 id="agent-的本质-一句话" tabindex="-1">Agent 的本质（一句话） <a class="header-anchor" href="#agent-的本质-一句话" aria-label="Permalink to &quot;Agent 的本质（一句话）&quot;">​</a></h2><blockquote><p><strong>Agent = LLM（大脑）+ 规划（拆任务）+ 记忆（记上下文）+ 工具（动手做）+ 反思（纠错）</strong>。 把「只会说话的模型」变成「能调用外部世界、能多步完成目标」的系统。</p></blockquote><hr><h2 id="为什么-agent-是「跨周期」方向" tabindex="-1">为什么 Agent 是「跨周期」方向？ <a class="header-anchor" href="#为什么-agent-是「跨周期」方向" aria-label="Permalink to &quot;为什么 Agent 是「跨周期」方向？&quot;">​</a></h2><ul><li><strong>框架会变</strong>（LangChain/LlamaIndex/AutoGPT 此起彼伏），但「规划-记忆-工具」的<strong>范式</strong>稳定。</li><li>它解决的是「让 AI 真正干活」的刚需，而非某个具体产品。</li><li>本篇只讲<strong>思想与边界</strong>，不绑定库——库过时了，思想还在。</li></ul><hr><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><ol><li><code>01-架构范式</code>：先懂 Agent 怎么「思考-行动」</li><li><code>02-RAG</code>：最落地的 Agent 能力（知识接入）</li><li><code>03-记忆与工具</code>：让 Agent 持久、能动手</li><li><code>04-MCP与多Agent</code>：规模化协作</li><li><code>05-工程化</code>：从 demo 到生产</li></ol><hr><p>➡️ 下一步：<a href="./01-Agent架构范式">01-Agent 架构范式</a></p>',16)])])}const u=e(r,[["render",o]]);export{s as __pageData,u as default};
